// Nota: Si no tienes el HEX del logo a mano, avísame y te lo pego completo otra vez.
// Por ahora usaré un placeholder para que compile si copias y pegas rápido, 
// pero asegúrate de poner tus arrays completos.

void iniciarPantalla() {
    u8g2.begin();
    u8g2.enableUTF8Print(); // Habilitar caracteres especiales si es necesario
}

void pantallaLogo() {
    u8g2.clearBuffer();
    // Dibuja el logo (asegurate de tener el array image_LogoPrevent...)
    // Si da error de compilación por el array vacío, comenta esta línea:
    u8g2.drawXBMP(0, 13, 127, 37, image_LogoPrevent_FondBlanco_bits); 
    u8g2.sendBuffer();
}

void pantallaCargando() {
    u8g2.clearBuffer();
    u8g2.setFontMode(1);
    u8g2.setBitmapMode(1);
    u8g2.setFont(u8g2_font_t0_11_tr);
    u8g2.drawStr(24, 23, "Inicializando");
    u8g2.drawStr(13, 35, "Espere para subir");
    u8g2.drawXBMP(57, 41, 15, 16, image_clock_bits);
    u8g2.drawFrame(3, 4, 122, 58);
    u8g2.sendBuffer();
}

void pantallaLista() {
    u8g2.clearBuffer();
    u8g2.setFontMode(1);
    u8g2.setBitmapMode(1);
    u8g2.setFont(u8g2_font_t0_11_tr);
    u8g2.drawStr(16, 30, "Plataforma lista");
    u8g2.drawXBMP(57, 35, 15, 16, image_heart_bits);
    u8g2.drawFrame(3, 3, 122, 58);
    u8g2.sendBuffer();
}

// Muestra Presión y Temperatura en una sola pantalla
void mostrarSensor(const char* titulo, int x, int y, float presion, float temp) {
    u8g2.clearBuffer();
    u8g2.setFontMode(1);
    u8g2.setBitmapMode(1);
    u8g2.setFont(u8g2_font_t0_11_tr);
    
    u8g2.drawStr(x, y, titulo); // Título dinámico
    
    // Cuadros
    u8g2.drawFrame(13, 16, 44, 33); // Cuadro Presión
    u8g2.drawFrame(70, 16, 44, 33); // Cuadro Temperatura

    // Etiquetas fijas
    u8g2.drawStr(36, 37, "kPa");
    u8g2.drawStr(98, 37, "C");
    u8g2.drawStr(23, 61, "Pres");
    u8g2.drawStr(81, 61, "Temp");
    
    u8g2.drawEllipse(96, 29, 1, 1); // Grado símbolo

    // --- DIBUJAR VALORES ---
    // Convertimos float a String con 1 decimal o 0 si es entero
    u8g2.setCursor(17, 37);
    u8g2.print(presion, 1); 

    u8g2.setCursor(82, 37);
    u8g2.print(temp, 1);

    u8g2.sendBuffer();
}

void mostrarPausa(String ip) {
    u8g2.clearBuffer();
    u8g2.setFont(u8g2_font_t0_11_tr);
    u8g2.drawStr(30, 20, "PAUSADO");
    u8g2.drawStr(10, 40, "WiFi IP:");
    u8g2.setCursor(10, 55);
    u8g2.print(ip);
    u8g2.drawFrame(0, 0, 128, 64);
    u8g2.sendBuffer();
}

void pantallaCalibrando() {
    u8g2.clearBuffer();
    u8g2.setFontMode(1);
    u8g2.setBitmapMode(1);
    
    // Layer 1
    u8g2.drawFrame(3, 3, 122, 58);

    // Layer 2
    u8g2.setFont(u8g2_font_t0_11_tr);
    u8g2.drawStr(34, 29, "Calibrando");

    // hour_glass_75 (El reloj de arena)
    u8g2.drawXBMP(59, 37, 11, 16, image_hour_glass_75_bits);

    u8g2.sendBuffer();
}